{"command":"cat << 'EOF' > mygotests.go
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"regexp"
	"strings"
	"text/template"
)

func main() {
	allFlag := flag.Bool("all", false, "")
	wFlag := flag.Bool("w", false, "")
	aiFlag := flag.Bool("ai", false, "")
	aiEndpoint := flag.String("ai-endpoint", "http://localhost:11434", "")
	flag.Parse()

	if len(flag.Args()) == 0 {
		return
	}

	filename := flag.Args()[0]
	fset := token.NewFileSet()
	node, err := parser.ParseFile(fset, filename, nil, parser.ParseComments)
	if err != nil {
		log.Fatal(err)
	}

	var buf bytes.Buffer
	buf.WriteString("package " + node.Name.Name + "\n\n")
	buf.WriteString("import (\n")
	buf.WriteString("\t\"reflect\"\n")
	buf.WriteString("\t\"testing\"\n")
	buf.WriteString(")\n\n")

	for _, decl := range node.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}

		if *allFlag {
			fmt.Printf("Generated Test%s\n", fn.Name.Name)
			// template logic will go here
		}
	}

	if *wFlag {
		outName := strings.TrimSuffix(filename, ".go") + "_test.go"
		ioutil.WriteFile(outName, buf.Bytes(), 0644)
	} else {
		fmt.Print(buf.String())
	}
}
EOF
go run mygotests.go -all user.go"}

