{"command":"cat << 'EOF' > generate.go
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
	"strings"
	"text/template"
)

type Field struct {
	Name string
	Type string
}

type FuncData struct {
	TestName       string
	FuncName       string
	Receiver       *Field
	ReceiverFields []Field
	Args           []Field
	Results        []Field
	ReturnsErr     bool
	NeedsReflect   bool
}

type TestData struct {
	PackageName string
	Imports     []string
	Funcs       []FuncData
}

func typeString(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.StarExpr:
		return "*" + typeString(e.X)
	case *ast.SelectorExpr:
		return typeString(e.X) + "." + e.Sel.Name
	case *ast.ArrayType:
		return "[]" + typeString(e.Elt)
	case *ast.MapType:
		return "map[" + typeString(e.Key) + "]" + typeString(e.Value)
	case *ast.FuncType:
		var params, results []string
		if e.Params != nil {
			for _, p := range e.Params.List {
				params = append(params, typeString(p.Type))
			}
		}
		if e.Results != nil {
			for _, r := range e.Results.List {
				results = append(results, typeString(r.Type))
			}
		}
		resStr := ""
		if len(results) > 0 {
			if len(results) == 1 {
				resStr = " " + results[0]
			} else {
				resStr = " (" + strings.Join(results, ", ") + ")"
			}
		}
		return "func(" + strings.Join(params, ", ") + ")" + resStr
	case *ast.InterfaceType:
		return "interface{}"
	case *ast.ChanType:
		return "chan " + typeString(e.Value)
	}
	return "interface{}"
}

func main() {
	if len(os.Args) < 2 {
		return
	}
	filename := os.Args[1]
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, filepath.Dir(filename), nil, 0)
	if err != nil {
		log.Fatal(err)
	}

	var node *ast.File
	var pkgName string
	for name, pkg := range pkgs {
		pkgName = name
		if f, ok := pkg.Files[filename]; ok {
			node = f
			break
		}
	}
	if node == nil {
		log.Fatal("file not found in AST")
	}

	// Dump functions
	for _, decl := range node.Decls {
		if fn, ok := decl.(*ast.FuncDecl); ok {
			fmt.Printf("Func: %s\n", fn.Name.Name)
			if fn.Recv != nil {
				fmt.Printf("  Recv: %s %s\n", fn.Recv.List[0].Names[0].Name, typeString(fn.Recv.List[0].Type))
			}
			if fn.Type.Params != nil {
				for _, p := range fn.Type.Params.List {
					for _, n := range p.Names {
						fmt.Printf("  Arg: %s %s\n", n.Name, typeString(p.Type))
					}
				}
			}
			if fn.Type.Results != nil {
				for i, r := range fn.Type.Results.List {
					name := ""
					if len(r.Names) > 0 {
						name = r.Names[0].Name
					} else {
						name = fmt.Sprintf("want%d", i)
					}
					fmt.Printf("  Res: %s %s\n", name, typeString(r.Type))
				}
			}
		}
	}
}
EOF
go run generate.go user.go"}

