		"options": map[string]interface{}{"seed": 42, "temperature": 0},
		"prompt":  prompt,
		"stream":  false,
	})

	for i := 0; i < 3; i++ {
		resp, err := client.Post(*aiEndpointFlag+"/api/generate", "application/json", bytes.NewReader(reqBody))
		if err == nil {
			defer resp.Body.Close()
			if resp.StatusCode == 200 {
				var res map[string]interface{}
				json.NewDecoder(resp.Body).Decode(&res)
				if msg, ok := res["message"].(map[string]interface{}); ok {
					return msg["content"].(string)
				}
				if respStr, ok := res["response"].(string); ok && respStr != "" {
					return respStr
				}
			}
		}
	}
	return "// TODO: Add test cases."
}

