func processFile(filename string) {
	absFile, _ := filepath.Abs(filename)
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, filepath.Dir(absFile), nil, 0)
	if err != nil {
		log.Fatal(err)
	}

	var node *ast.File
	var pkgNode *ast.Package
	for _, pkg := range pkgs {
		for fName, f := range pkg.Files {
			if filepath.Base(fName) == filepath.Base(absFile) {
				node = f
				pkgNode = pkg
				break
			}
		}
	}
	if node == nil {
		return
	}

	existingTests := make(map[string]bool)
	testFile := strings.TrimSuffix(absFile, ".go") + "_test.go"
	if _, err := os.Stat(testFile); err == nil {
		if testAST, err := parser.ParseFile(fset, testFile, nil, 0); err == nil {
			for _, decl := range testAST.Decls {
				if fn, ok := decl.(*ast.FuncDecl); ok && strings.HasPrefix(fn.Name.Name, "Test") {
					existingTests[fn.Name.Name] = true
				}
			}
		}
	}

	var data TestData
	data.PackageName = node.Name.Name
	needsReflect := false
	needsTesting := false

	for _, decl := range node.Decls {
		if fn, ok := decl.(*ast.FuncDecl); ok {
			if !*allFlag && fn.Name.Name != *onlyFlag { 
				continue
			}

			funcData := FuncData{
				FuncName: fn.Name.Name,
				TestName: "Test" + fn.Name.Name,
			}

			if fn.Recv != nil && len(fn.Recv.List) > 0 {
				recvName := "m"
				if len(fn.Recv.List[0].Names) > 0 {
					recvName = fn.Recv.List[0].Names[0].Name
				}
				recvType := typeString(fn.Recv.List[0].Type)
				funcData.Receiver = &Field{Name: recvName, Type: recvType}
				structName := strings.TrimPrefix(recvType, "*")
				funcData.TestName = "Test" + structName + "_" + fn.Name.Name
				funcData.ReceiverFields = getStructFields(pkgNode, structName)
			}

			if existingTests[funcData.TestName] {
				continue
			}

			fmt.Printf("Generated %s\n", funcData.TestName)
			needsTesting = true

			if fn.Type.Params != nil {
				for _, p := range fn.Type.Params.List {
					typ := typeString(p.Type)
					for _, n := range p.Names {
						funcData.Args = append(funcData.Args, Field{Name: n.Name, Type: typ})
					}
				}
			}

			numNonError := 0
			if fn.Type.Results != nil {
				for _, r := range fn.Type.Results.List {
					if typeString(r.Type) != "error" {
						if len(r.Names) > 0 {
							numNonError += len(r.Names)
						} else {
							numNonError++
						}
					}
				}
			}

			if fn.Type.Results != nil {
				for i, r := range fn.Type.Results.List {
					typ := typeString(r.Type)
					if checkReflect(typ) {
						needsReflect = true
					}
					if typ == "error" && i == len(fn.Type.Results.List)-1 {
						funcData.ReturnsErr = true
						funcData.Results = append(funcData.Results, Field{Name: "err", Type: typ})
					} else {
						name := "want"
						if numNonError > 1 {
							name = fmt.Sprintf("want%d", len(funcData.Results))
							if name == "want0" { name = "want" }
						}
						funcData.Results = append(funcData.Results, Field{Name: name, Type: typ})
					}
				}
			}

			data.Funcs = append(data.Funcs, funcData)
		}
	}

	if len(data.Funcs) == 0 {
		if *aiFlag {
			fmt.Printf("No tests generated for %s\n", filepath.Base(filename))
		}
		return
	}

	if needsReflect {
		data.Imports = append(data.Imports, "reflect")
	}
	if needsTesting {
		data.Imports = append(data.Imports, "testing")
	}

	tmpl := template.Must(template.New("test").Funcs(template.FuncMap{
		"trimPrefix": trimPrefix,
		"checkReflect": checkReflect,
	}).Parse(testTmpl))

	var buf bytes.Buffer
	err = tmpl.Execute(&buf, data)
	if err != nil {
		log.Fatal(err)
	}

	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		formatted = buf.Bytes() // fallback if format fails
	}

	if *wFlag {
		ioutil.WriteFile(testFile, formatted, 0644)
	} else {
		fmt.Print(string(formatted))
	}
}
