func typeString(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.StarExpr:
		return "*" + typeString(e.X)
	case *ast.SelectorExpr:
		return typeString(e.X) + "." + e.Sel.Name
	case *ast.ArrayType:
		return "[]" + typeString(e.Elt)
	case *ast.MapType:
		return "map[" + typeString(e.Key) + "]" + typeString(e.Value)
	case *ast.FuncType:
		var params, results []string
		if e.Params != nil {
			for _, p := range e.Params.List {
				params = append(params, typeString(p.Type))
			}
		}
		if e.Results != nil {
			for _, r := range e.Results.List {
				results = append(results, typeString(r.Type))
			}
		}
		resStr := ""
		if len(results) > 0 {
			if len(results) == 1 {
				resStr = " " + results[0]
			} else {
				resStr = " (" + strings.Join(results, ", ") + ")"
			}
		}
		return "func(" + strings.Join(params, ", ") + ")" + resStr
	case *ast.InterfaceType:
		return "interface{}"
	case *ast.ChanType:
		return "chan " + typeString(e.Value)
	}
	return "interface{}"
}

func getStructFields(pkg *ast.Package, structName string) []Field {
	var fields []Field
	for _, f := range pkg.Files {
		for _, decl := range f.Decls {
			if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.TYPE {
				for _, spec := range gen.Specs {
					if typeSpec, ok := spec.(*ast.TypeSpec); ok && typeSpec.Name.Name == structName {
						if structType, ok := typeSpec.Type.(*ast.StructType); ok {
							for _, fld := range structType.Fields.List {
								if len(fld.Names) == 0 {
									fields = append(fields, Field{Name: typeString(fld.Type), Type: typeString(fld.Type)})
								}
								for _, n := range fld.Names {
									fields = append(fields, Field{Name: n.Name, Type: typeString(fld.Type)})
								}
							}
						}
					}
				}
			}
		}
	}
	return fields
}

